/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-9","number":9,"title":"Harmonic Chord Engines","skillBand":"Textbook","duration":"From the course textbook","summary":"The Launchkey MK4 61 contains three distinct polyphonic chord engines: Chord Map, User Chord, and Fixed Chord. These engines transform single-finger pad or key inputs into harmonically complex voicings. This module establishes the structura","modules":[{"id":"launchkey-m-9-1-1","code":"9.1","title":"Harmonic Chord Engines","blurb":"The Launchkey MK4 61 contains three distinct polyphonic chord engines: Chord Map, User Chord, and Fixed Chord. These engines transform single-finger pad or key inputs into harmonically complex voicings. This module establishes the structura","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-25","title":"Section overview","blocks":[{"type":"step","title":"Section 9.1 — Triad/Voicing Architecture & Channel Specifications","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Launchkey MK4 61 contains three distinct polyphonic chord engines: <strong>Chord Map</strong>, <strong>User Chord</strong>, and <strong>Fixed Chord</strong>. These engines transform single-finger pad or key inputs into harmonically complex voicings. This module establishes the structural taxonomy of the three chord engines, hardware access paths, and the mandatory multi-track MIDI channel routing standard."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Classify the operational boundaries of the three chord generation engines: <strong>Chord Map</strong>, <strong>User Chord</strong>, and <strong>Fixed Chord</strong>.","Identify the dedicated top-panel hardware switches for Chord Map and Fixed Chord on the 61-key chassis.","Formulate the technical requirement for dedicated <strong>MIDI Channel 3</strong> transmission.","Eliminate multi-track DAW channel contention between keys and chord engines."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-1-1","title":"9.1.1: Taxonomy of the Three Chord Engines","blocks":[{"type":"step","title":"9.1.1: Taxonomy of the Three Chord Engines","blocks":[{"type":"prose","html":"The Launchkey MK4 61 provides three specialized approaches to chord generation:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    LAUNCHKEY MK4 61 CHORD ENGINE TAXONOMY                     |\n+-------------------+---------------------+-------------------------------------+\n| Chord Engine      | Physical Trigger    | Core Harmonic Mechanism             |\n+-------------------+---------------------+-------------------------------------+\n| **Chord Map**     | Left 8 RGB Pads     | Generative, 40-bank scale-quantized |\n|                   |                     | progressions with dynamic modifiers |\n+-------------------+---------------------+-------------------------------------+\n| **User Chord**    | 16 RGB Pads         | 16 custom user-captured voicings    |\n|                   |                     | (up to 6 notes per pad)             |\n+-------------------+---------------------+-------------------------------------+\n| **Fixed Chord**   | 61-Key Keybed       | Transposes a stored interval shape  |\n|                   |                     | across every physical piano key     |\n+-------------------+---------------------+-------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-9-1-2","title":"9.1.2: Dedicated Hardware Access on the 61-Key Chassis","blocks":[{"type":"step","title":"9.1.2: Dedicated Hardware Access on the 61-Key Chassis","blocks":[{"type":"prose","html":"Unlike smaller compact controllers (e.g., Launchkey Mini, which requires <code>Shift + Pad 12</code> to enter Chord Map), the Launchkey MK4 61 features <strong>dedicated physical switches</strong>:"},{"type":"list","items":["<strong>Chord Map</strong>: Direct top-panel button labeled <code>Chord Map</code>. Pressing it instantly converts the pad matrix into the 8-chord / 6-performance modifier array.","<strong>Fixed Chord</strong>: Direct top-panel button labeled <code>Fixed Chord</code>.","<strong>User Chord</strong>: Accessed via <code>Shift + Pad 11</code>."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-9-1-3","title":"9.1.3: Dedicated MIDI Channel 3 Mandate","blocks":[{"type":"step","title":"9.1.3: Dedicated MIDI Channel 3 Mandate","blocks":[{"type":"prose","html":"All chord generation subsystems transmit on <strong>MIDI Channel 3</strong> (configured in Settings -&gt; <code>Chords Ch</code>)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       MULTI-TIMBRAL STUDIO CHANNEL TOPOLOGY\n+───────────────────────────────────────────────────────────────+\n| Keybed (Manual Leads/Bass) ──► MIDI Ch 1 ──► DAW Track 1 (Lead)|\n| Chord Engines (Pads/Keys)  ──► MIDI Ch 3 ──► DAW Track 2 (Pads)|\n+───────────────────────────────────────────────────────────────+</pre>"},{"type":"prose","html":"<em>Routing Requirement</em>: To play keyboard leads on Track 1 while simultaneously triggering rich pad chords from the pads on Track 2, set Track 1's MIDI Input to <strong>Launchkey MK4 MIDI (Channel 1)</strong> and Track 2's MIDI Input to <strong>Launchkey MK4 MIDI (Channel 3)</strong>."}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Categorization of Chord Map vs User Chord vs Fixed Chord; dedicated Chord Map / Fixed Chord switches on the 61; dedicated MIDI Channel 3 default; multi-channel DAW track isolation.","<strong>mustNotCover</strong>: Applying Mini Shift-pad rules to the 61; assuming chords share Channel 1 by default."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In your DAW, create two separate virtual instrument tracks. Set Track 1 input to MIDI Channel 1 (Keys) and Track 2 input to MIDI Channel 3 (Chords). Engage Chord Map and play keys and pads simultaneously."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Keybed triggers only Track 1.","Chord pads trigger only Track 2.","Both instruments play harmoniously without channel crosstalk."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-9-2-2","code":"9.2","title":"Harmonic Chord Engines","blurb":"Chord Map is an advanced generative harmony engine that maps dynamically calculated diatonic and extended chord voicings onto the 16-pad matrix. The left 8 pads trigger 40 banks of musically related chords, while the right 6 pads provide re","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-26","title":"Section overview","blocks":[{"type":"step","title":"Section 9.2 — Generative Chord Map Engine","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Chord Map is an advanced generative harmony engine that maps dynamically calculated diatonic and extended chord voicings onto the 16-pad matrix. The left 8 pads trigger 40 banks of musically related chords, while the right 6 pads provide real-time performance modifiers (Manual Arpeggiation, Inversions, Bass/Chord Splitting). Continuous encoders dynamically modulate harmonic complexity, octave spread, and strum roll."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Initialize the Chord Map engine via the dedicated top-panel switch.","Formulate the spatial layout of the 8 Chord Trigger Pads versus the 6 Performance Modifier Pads.","Modulate harmonic complexity and voicing characteristics using Encoders 1–4 (<strong>Adventure</strong>, <strong>Explore</strong>, <strong>Spread</strong>, <strong>Roll</strong>).","Execute real-time harmonic modifications using the 6 Performance Pads (Manual Arp Up/Down, Inversion Up/Down, Split Bass+Chord, Split Left/Right).","Apply the single-performance-pad mutual exclusivity rule and latch modifiers via <code>Scene Launch &gt;</code>.","Transpose chord pad octaves and synchronize chord maps via Ableton Live Global Scale."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-2-1","title":"9.2.1: Chord Map Surface Architecture","blocks":[{"type":"step","title":"9.2.1: Chord Map Surface Architecture","blocks":[{"type":"prose","html":"Pressing the dedicated <code>Chord Map</code> button divides the 2×8 pad matrix into two specialized zones:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    CHORD MAP 16-PAD SPATIAL TOPOLOGY                          |\n+---------------------------------------+---+-----------------------------------+\n| LEFT 8 PADS: CHORD TRIGGERS           |   | RIGHT 6 PADS: PERFORMANCE PADS    |\n+---------------------------------------+---+-----------------------------------+\n| [Pad 1: Ch 1] [Pad 2: Ch 2] [Pad 3: Ch 3] [Pad 4: Ch 4] | [Pad 6: Arp ▲] [Pad 7: Inv ▲] [Pad 8: Split B+C] |\n| [Pad 9: Ch 5] [Pad 10:Ch 6] [Pad 11:Ch 7] [Pad 12:Ch 8] | [Pad 14:Arp ▼] [Pad 15:Inv ▼] [Pad 16:Split L/R] |\n+---------------------------------------+---+-----------------------------------+\n*(Note: Pads 5 and 13 are unassigned/blank spacers in standard Chord Map layout).*</pre>"},{"type":"list","items":["<strong>Left 8 Pads (Pads 1–4 Top, Pads 9–12 Bottom)</strong>: Trigger 8 musically related diatonic/extended chords.","<strong>OLED Visual Feedback</strong>: Striking any chord pad generates an immediate readout showing the chord name (e.g., <code>D min9</code>) and a graphic mini-keyboard indicating the exact keys being voiced."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-2-2","title":"9.2.2: Encoders 1–4 Harmonic Modulation","blocks":[{"type":"step","title":"9.2.2: Encoders 1–4 Harmonic Modulation","blocks":[{"type":"prose","html":"When Chord Map is active, Encoders 1–4 control the internal generative harmonic matrix:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    CHORD MAP CONTINUOUS ENCODER MATRIX                        |\n+---------------+-------------------+-------------------------------------------+\n| Encoder       | Parameter Name    | Musical Operational Behavior              |\n+---------------+-------------------+-------------------------------------------+\n| **Encoder 1** | **Adventure**     | Increases harmonic complexity:            |\n|               |                   | Module 1: Simple diatonic triads           |\n|               |                   | Module 2–3: 7ths, 9ths, suspended chords   |\n|               |                   | Module 4–5: Extended 11ths, 13ths, altered |\n+---------------+-------------------+-------------------------------------------+\n| **Encoder 2** | **Explore**       | Cycles through alternative chord sets     |\n|               |                   | available at the current Adventure level  |\n|               |                   | *(Total 40 banks per Chord Set)*          |\n+---------------+-------------------+-------------------------------------------+\n| **Encoder 3** | **Spread**        | Expands chord tones outward across octaves|\n|               |                   | for wide, lush stereo acoustic voicings   |\n+---------------+-------------------+-------------------------------------------+\n| **Encoder 4** | **Roll**          | Introduces micro-timing delay between     |\n|               |                   | notes, creating a natural guitar strum    |\n+---------------+-------------------+-------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-9-2-3","title":"9.2.3: The 6 Performance Modifier Pads","blocks":[{"type":"step","title":"9.2.3: The 6 Performance Modifier Pads","blocks":[{"type":"prose","html":"The right 6 pads do not generate sound independently; instead, they dynamically alter the playback behavior of whichever chord pad is selected or held:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    THE 6 PERFORMANCE MODIFIER PADS                            |\n+--------+----------------------+-----------------------------------------------+\n| Pad #  | Modifier Name        | Execution Mechanics                           |\n+--------+----------------------+-----------------------------------------------+\n| **6**  | **Manual Arp Up**    | Each press voices the next higher chord note, |\n|        |                      | ascending from lowest to highest, then resets |\n+--------+----------------------+-----------------------------------------------+\n| **14** | **Manual Arp Down**  | Each press voices the next lower chord note,  |\n|        |                      | descending from highest to lowest, then resets|\n+--------+----------------------+-----------------------------------------------+\n| **7**  | **Inversion Up**     | Cycles chord inversions per press:            |\n|        |                      | Press 1: Root -&gt; Press 2: 1st Inv -&gt;          |\n|        |                      | Press 3: 2nd Inv -&gt; Press 4: 3rd Inv -&gt; Reset |\n+--------+----------------------+-----------------------------------------------+\n| **15** | **Inversion Down**   | Cycles inversions downward per press          |\n+--------+----------------------+-----------------------------------------------+\n| **8**  | **Split Bass+Chord** | Press 1: Plays lowest bass note only          |\n|        |                      | Press 2: Plays remaining upper chord block    |\n+--------+----------------------+-----------------------------------------------+\n| **16** | **Split Left/Right** | Press 1: Plays two lowest chord notes         |\n|        |                      | Press 2: Plays remaining higher notes         |\n+--------+----------------------+-----------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-9-2-4","title":"9.2.4: Mutual Exclusivity, Latching & Reset Rules","blocks":[{"type":"step","title":"9.2.4: Mutual Exclusivity, Latching & Reset Rules","blocks":[{"type":"list","items":["<strong>Single Modifier Rule</strong>: <strong>Only one performance modifier pad can be active at any given time</strong>. Pressing a new performance pad immediately deactivates the previous modifier.","<strong>Latching with <code>Scene Launch &gt;</code></strong>:","Pressing <code>Scene Launch &gt;</code> locks Performance Pad Latching (the <code>&gt;</code> button illuminates <strong>solid white</strong>).","When latched, modifier states persist without holding. Pressing <code>Scene Launch &gt;</code> again unlatches and clears all active performance modifiers.","<strong>Reset Rules</strong>:","Striking a new Chord Pad immediately resets the Inversion and Manual Arp cycles back to Step 1.","Releasing an unlatched performance pad instantly resets the cycle."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-2-5","title":"9.2.5: Octave Transposition & Ableton Live Global Scale Sync","blocks":[{"type":"step","title":"9.2.5: Octave Transposition & Ableton Live Global Scale Sync","blocks":[{"type":"list","items":["<strong>Octave Transposition</strong>: Pressing <code>Pad Bank Up / Down</code> shifts the pitch center of the 8 chord pads up or down in discrete octave increments.","<strong>Ableton Live Global Scale Sync</strong>: When connected to Ableton Live 12, changing Live’s project Scale (or opening an existing Live set) automatically transmits the scale to the Launchkey via SysEx, synchronizing the Chord Map engine to the exact musical key of the DAW session."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Chord Map button access; 8 chord pads + 6 performance pads layout; Encoders 1–4 (Adventure, Explore, Spread, Roll); all 6 performance pad actions; single performance pad limit; latching via <code>Scene Launch &gt;</code> (white LED); reset rules; octave navigation; Live Global Scale sync.","<strong>mustNotCover</strong>: Attempting to engage two performance pads simultaneously; Mini Shift-pad Chord Map methods."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Engage Chord Map. Play Chord Pad 1, turn <code>Adventure</code> to Module 3, and turn <code>Roll</code> clockwise. Latch <code>Scene Launch &gt;</code> (white LED), press <code>Inversion Up</code> (Pad 7) four times to cycle through the C major inversion table, and then press <code>Scene Launch &gt;</code> to release latch."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Roll introduces audible strumming delay.","Inversion Up cycles: Root -&gt; 1st Inversion -&gt; 2nd Inversion -&gt; 3rd Inversion -&gt; Root.","Releasing latch resets performance modifiers cleanly."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-9-3-3","code":"9.3","title":"Harmonic Chord Engines","blurb":"The Fixed Chord engine allows performers to capture a specific polyphonic harmonic shape (up to 6 notes) and play that exact interval relationship across the entire 61-key keybed from any single root key. This module covers chord capture, c","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-27","title":"Section overview","blocks":[{"type":"step","title":"Section 9.3 — Fixed Transposition Chord Engine","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Fixed Chord engine allows performers to capture a specific polyphonic harmonic shape (up to 6 notes) and play that exact interval relationship across the entire 61-key keybed from any single root key. This module covers chord capture, chromatic parallel transposition, toggle activation, the 6-note polyphony ceiling, and single-key memory clearing."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Assign and store a custom harmonic interval set into Fixed Chord memory.","Play polyphonic chord voicings chromatically from single keybed triggers.","Toggle the Fixed Chord engine on and off via the dedicated top-panel switch.","Clear stored chord intervals and restore standard monophonic/polyphonic single-key operation."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-3-1","title":"9.3.1: Assigning Fixed Chord Intervals","blocks":[{"type":"step","title":"9.3.1: Assigning Fixed Chord Intervals","blocks":[{"type":"prose","html":"Fixed Chord captures the relative mathematical intervals between depressed keys:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">FIXED CHORD CAPTURE STEP-BY-STEP WORKFLOW:\n1. Press and HOLD the dedicated [ Fixed Chord ] button.\n2. While holding the button, play up to 6 keys on the keybed.\n   - Example: Play C3, G3, C4 (Root, Perfect 5th, Octave).\n3. Release the [ Fixed Chord ] button.\n4. The interval shape is now permanently stored in internal memory.</pre>"},{"type":"prose","html":"<em>Hardware Note Limit</em>: The Fixed Chord engine accepts up to <strong>6 notes maximum</strong>. Any additional keys depressed beyond 6 are discarded."}]}],"minutes":8},{"id":"launchkey-l-9-3-2","title":"9.3.2: Chromatic Parallel Transposition","blocks":[{"type":"step","title":"9.3.2: Chromatic Parallel Transposition","blocks":[{"type":"prose","html":"Once stored:"},{"type":"list","items":["<strong>Single-Key Triggering</strong>: Pressing any single key on the keybed treats that key as the root and transposes all stored intervals in parallel.","<strong>Parallel Harmony</strong>: Unlike Scale Mode (which constrains intervals diatonically), Fixed Chord transposes the exact chromatic interval formula (e.g., Major 7th, Minor 9th, Power Chord) across all 12 semitones."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-3-3","title":"9.3.3: Toggling & Re-assignment","blocks":[{"type":"step","title":"9.3.3: Toggling & Re-assignment","blocks":[{"type":"list","items":["<strong>Toggle On / Off</strong>: Pressing the <code>Fixed Chord</code> button turns the mode on (illuminated solid bright blue) and off (unlit).","<strong>Re-assignment</strong>: Storing a new chord immediately overwrites the previously stored interval set."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-9-3-4","title":"9.3.4: Clearing Fixed Chord Memory","blocks":[{"type":"step","title":"9.3.4: Clearing Fixed Chord Memory","blocks":[{"type":"prose","html":"To completely clear the stored chord formula and return single keys to single notes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">FIXED CHORD CLEAR WORKFLOW:\n1. Press and HOLD the [ Fixed Chord ] button.\n2. Press any SINGLE key on the keybed.\n3. Release the [ Fixed Chord ] button.\n4. The stored chord is cleared; single keys now output single notes.</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Hold Fixed Chord + play up to 6 keys to assign; single-key chromatic parallel transposition; button toggle; hold Fixed Chord + press single key to clear.","<strong>mustNotCover</strong>: Speculation regarding multi-preset Fixed Chord banks on the 61 (only 1 active Fixed Chord is stored at a time)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Program a Minor 9th chord (Root, Minor 3rd, Perfect 5th, Minor 7th, 9th) into Fixed Chord. Play it on roots C, F, and G. Then execute the single-key clear procedure to return the keybed to normal single-note operation."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Fixed Chord accurately transposes the 5-note voicing across all root keys.","Clear procedure successfully restores single-note key output."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-9-4-4","code":"9.4","title":"Harmonic Chord Engines","blurb":"Combining the Scale Engine with the three Chord Engines allows performers to create rich, multi-timbral studio arrangements while guaranteeing diatonic harmonic alignment. This module details the interaction between Scale Mode and Chord Set","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-28","title":"Section overview","blocks":[{"type":"step","title":"Section 9.4 — Scale-Quantized Harmonic Integration","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Combining the Scale Engine with the three Chord Engines allows performers to create rich, multi-timbral studio arrangements while guaranteeing diatonic harmonic alignment. This module details the interaction between Scale Mode and Chord Sets, multi-channel DAW routing architecture, and non-destructive parameter editing."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate how active Scale selection dictates the harmonic library loaded by the Chord Map engine.","Execute non-destructive Scale adjustments during chord performance using long-press inspection.","Establish a dual-track multi-channel DAW template routing Keys (Channel 1) and Chord Pads (Channel 3) to independent virtual instruments.","Complete Assessment Gate G."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-4-1","title":"9.4.1: Scale-to-Chord-Set Mapping Matrix","blocks":[{"type":"step","title":"9.4.1: Scale-to-Chord-Set Mapping Matrix","blocks":[{"type":"prose","html":"When both <code>Scale</code> and <code>Chord Map</code> are active:"},{"type":"list","items":["<strong>Dynamic Chord Set Selection</strong>: The active Scale Type (from the 30 official scales) automatically loads an associative <strong>Chord Set</strong> into Chord Map.","<strong>Harmonic Consistency</strong>: Selecting <code>Minor</code> populates the 8 chord pads with natural minor diatonic triads and 7th chords; selecting <code>Dorian</code> automatically voices minor 7th and dominant 7th chords incorporating the natural 6th degree."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-9-4-2","title":"9.4.2: Non-Destructive Long-Press Editing","blocks":[{"type":"step","title":"9.4.2: Non-Destructive Long-Press Editing","blocks":[{"type":"prose","html":"During a performance:"},{"type":"list","items":["Long-pressing <code>Scale</code>, <code>Chord Map</code>, or <code>Arp</code> brings up that engine's parameter page on the OLED screen and continuous encoders without disabling or interrupting active sound generation."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-9-4-3","title":"9.4.3: Dual-Channel Performance Reality","blocks":[{"type":"step","title":"9.4.3: Dual-Channel Performance Reality","blocks":[{"type":"prose","html":"A common user error is routing a single DAW track to listen to \"All Channels\" and expecting keys and chord pads to trigger different instruments."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       MULTI-TIMBRAL STUDIO ROUTING BEST PRACTICE\n+-------------------------------------------------------------------------------+\n| DAW Track 1 (Lead / Melody Synth):                                            |\n| - MIDI Input: Launchkey MK4 61 MIDI -&gt; Channel 1 (Part A Keybed)              |\n| - Monitor: In / Auto -&gt; Output: Audio Track 1                                 |\n+-------------------------------------------------------------------------------+\n| DAW Track 2 (Polyphonic Pad / Electric Piano):                                |\n| - MIDI Input: Launchkey MK4 61 MIDI -&gt; Channel 3 (Chord Engines)              |\n| - Monitor: In / Auto -&gt; Output: Audio Track 2                                 |\n+-------------------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Scale-to-Chord-Set coupling; long-press non-destructive access; Channel 1 (Keys) vs Channel 3 (Chords) studio routing.","<strong>mustNotCover</strong>: Claiming keys and pads must share a single channel."],"ordered":false}]},{"type":"step","title":"Assessment Gate G (Chord Engines Validation)","blocks":[{"type":"prose","html":"<strong>Objective</strong>: Demonstrate complete operational mastery of Chord Map, User Chord, Fixed Chord, and multi-channel studio routing."},{"type":"prose","html":"<strong>Self-Assessment Checklist</strong>:"},{"type":"list","items":["[ ] Set up two DAW tracks listening to MIDI Channel 1 (Keys) and MIDI Channel 3 (Chords).","[ ] Engage Chord Map, select <code>Adventure 2</code>, play an 8-bar progression from the left 8 pads, and record the output on Channel 3.","[ ] Switch to User Chord Mode (<code>Shift + Pad 11</code>), capture a custom 4-note voicing on Pad 9, test it, and then erase it using <code>Function</code> + Red Pad.","[ ] Engage Fixed Chord, program a 3-note triad shape, play a phrase across 3 octaves on the keybed, and clear the chord using <code>Fixed Chord</code> + Single Key."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
